from fastapi import FastAPI, Depends, HTTPException
from sqlalchemy.ext.asyncio import create_async_engine, AsyncSession
from sqlalchemy.orm import sessionmaker
from sqlalchemy import text
from pydantic import BaseModel
import asyncio

app = FastAPI()

DATABASE_URL = "postgresql+asyncpg://app:secret@db-pooler:6432/maindb"

engine = create_async_engine(
    DATABASE_URL,
    pool_size=20,
    max_overflow=10,
    pool_pre_ping=True,
    pool_recycle=300
)

AsyncSessionLocal = sessionmaker(engine, class_=AsyncSession, expire_on_commit=False)


async def get_db():
    async with AsyncSessionLocal() as session:
        yield session


class TransferRequest(BaseModel):
    from_account: str
    to_account: str
    amount: float


class BalanceUpdate(BaseModel):
    account_id: str
    new_limit: float


@app.post("/transfer")
async def transfer_funds(req: TransferRequest, db: AsyncSession = Depends(get_db)):
    """Transfer funds between accounts. Uses optimistic concurrency."""
    # Read current balance
    result = await db.execute(
        text("SELECT balance, version FROM accounts WHERE account_id = :aid"),
        {"aid": req.from_account}
    )
    row = result.fetchone()
    if not row:
        raise HTTPException(status_code=404, detail="Source account not found")

    balance, version = row

    if balance < req.amount:
        raise HTTPException(status_code=400, detail="Insufficient funds")

    # Debit source - race condition window between read and write
    # No SELECT FOR UPDATE, no explicit row lock
    update_result = await db.execute(
        text(
            "UPDATE accounts SET balance = balance - :amount, version = version + 1 "
            "WHERE account_id = :aid AND version = :ver"
        ),
        {"amount": req.amount, "aid": req.from_account, "ver": version}
    )

    if update_result.rowcount == 0:
        # Optimistic lock failed - but we don't retry, just error
        raise HTTPException(status_code=409, detail="Concurrent modification")

    # Credit destination
    await db.execute(
        text(
            "UPDATE accounts SET balance = balance + :amount, version = version + 1 "
            "WHERE account_id = :aid"
        ),
        {"amount": req.amount, "aid": req.to_account}
    )

    await db.commit()
    return {"status": "completed", "amount": req.amount}


@app.post("/admin/update-limit")
async def update_credit_limit(req: BalanceUpdate, db: AsyncSession = Depends(get_db)):
    """Admin endpoint to update account credit limit."""
    # Direct update without version check - intentional for admin ops
    await db.execute(
        text("UPDATE accounts SET credit_limit = :limit WHERE account_id = :aid"),
        {"limit": req.new_limit, "aid": req.account_id}
    )
    await db.commit()
    return {"status": "updated"}


@app.get("/balance/{account_id}")
async def get_balance(account_id: str, db: AsyncSession = Depends(get_db)):
    result = await db.execute(
        text("SELECT balance, credit_limit FROM accounts WHERE account_id = :aid"),
        {"aid": account_id}
    )
    row = result.fetchone()
    if not row:
        raise HTTPException(status_code=404, detail="Account not found")
    return {"account_id": account_id, "balance": row[0], "credit_limit": row[1]}


@app.post("/batch-transfer")
async def batch_transfer(transfers: list[TransferRequest], db: AsyncSession = Depends(get_db)):
    """Process multiple transfers concurrently within same session."""
    tasks = []
    for t in transfers:
        tasks.append(_do_single_transfer(t, db))
    results = await asyncio.gather(*tasks, return_exceptions=True)
    return {"results": [str(r) for r in results]}


async def _do_single_transfer(req: TransferRequest, db: AsyncSession):
    result = await db.execute(
        text("SELECT balance FROM accounts WHERE account_id = :aid"),
        {"aid": req.from_account}
    )
    row = result.fetchone()
    if not row or row[0] < req.amount:
        return "failed: insufficient funds or not found"

    await db.execute(
        text("UPDATE accounts SET balance = balance - :amount WHERE account_id = :aid"),
        {"amount": req.amount, "aid": req.from_account}
    )
    await db.execute(
        text("UPDATE accounts SET balance = balance + :amount WHERE account_id = :aid"),
        {"amount": req.amount, "aid": req.to_account}
    )
    return "success"
